import os, re, glob

def load_grids():
    d = os.path.normpath(os.environ.get('RLM_SESSION_DIR', ''))
    if not d:
        return {}

    # Try to find session file
    session_file = os.path.join(d, '../../sessions/' + os.path.basename(d) + '.jsonl')

    G = {}
    try:
        with open(session_file, 'r') as f:
            content = f.read()

        # Parse demo pairs from the log
        for match in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', content):
            k, h, w = match[1], int(match[2]), int(match[3])
            # Get the next grid (next h lines that contain digits)
            rest = content[match.end():]
            rows = []
            for line in rest.split('\n')[:h]:
                if ' ' in line and line.strip():
                    rows.append(line.strip().split())
            if not rows:
                continue
            if k not in G and all(len(r) == w for r in rows):
                G[k] = [[int(x) for x in r] for r in rows]
    except Exception as e:
        print(f"Note: {e}")

    return G

G = load_grids()
print(f"Loaded {len(G)} grid entries")
for k, g in G.items():
    print(f"  {k}: {g}")

