# Simple key-value parsing
def parse_session_log(content):
    grids = {}
    current_key = None
    current_grid = []
    current_dims = None

    for line in content.split('\n'):
        if 'x' in line and 'input' in line.lower() and current_key is None:
            # Try to parse as key
            m = re.match(r'(\w+) (input|output) (\d+)x(\d+):', line)
            if m:
                current_key = m.group(1)
                current_dims = (int(m.group(3)), int(m.group(4)))
                current_grid = []
        elif current_key and current_dims:
            # Continuation - parse grid rows
            parts = line.strip().split()
            if parts and parts[-1].isdigit() and len(parts) > 0:
                current_grid.append(line.strip().split())
                if len(line.strip()) < 50:  # End of current entry
                    if all(len(r) == current_dims[1] for r in current_grid):
                        grids[current_key] = [[int(x) for x in r] for r in current_grid]
                    current_grid = []
                    current_dims = None

    return grids

